// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;
import "./IBEP20.sol";
import {Advert,Shared} from "./Advert.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

contract Trade is Initializable{

    struct trade{
        string advertId;
        address payable buyer;
        uint amount;
        bool closed;
    }
    address ADMIN_ADDRESS;
    Advert A;

    mapping(string=>trade) public Trades;
    trade[] internal __trades;
	
	event TokenTransfered(string tradeId);
	event InitTrade(string tradeId);
    event AdvertClosed(string advertId);
    event TradeClosed(string tradeId);

    function initialize(address _admin,address payable _advert)public initializer{
        ADMIN_ADDRESS = _admin;
        A = Advert(_advert);
    }

    /*
     string memory !== string storage, but if they are identical, their hashed would be thesame
    */
    function closeAdvert(string memory _advertId)external{
        address adOwner = A.getAdvertOwner(_advertId);
        bool flag = false;
        require(adOwner == msg.sender,"Unauthorized to close contract");
        for(uint i = 0;i< __trades.length;i++){
            
            if(keccak256(abi.encodePacked(__trades[i].advertId)) == keccak256(abi.encodePacked(_advertId))){
                if(__trades[i].closed == true){
                    flag = true;
                }
            }
        }
        require(flag == true,"cannot close active advert");
        A.closeAdvert(_advertId);
        emit AdvertClosed(_advertId);
    }

    function closeTrade(string memory _tradeId)external{
        trade storage _trade = Trades[_tradeId];
        require(msg.sender == _trade.buyer,"unauthorized to close trade");
        A.addBalance(_trade.advertId, _trade.amount);
         _trade.closed = true;
        emit TradeClosed(_tradeId);
    }

    function createTrade(string memory _tradeId, string memory _advertId,uint _amount) external {
        uint advertBalance = A.getBalance(_advertId);
        require(_amount <= advertBalance,"insufficient balance to initiate trade");
        trade memory _t = trade(_advertId,payable(msg.sender),_amount,false);
        A.deductBalance(_advertId,_amount);
        Trades[_tradeId] = _t;
        __trades.push(_t);
		emit InitTrade(_tradeId);
    }
    
   receive() external payable{}

    function transferAsset(string memory _tradeId) external{
        trade memory T = Trades[_tradeId];
        require(T.closed == false,"trade is closed");
        A.transferAsset(_tradeId,T.advertId,payable(msg.sender),T.buyer,T.amount);
		emit TokenTransfered(_tradeId);
    }

    function adminCancelTrade(string memory _tradeId) external{
        require(msg.sender == ADMIN_ADDRESS,"Unauthorized to make transaction");
        trade storage _t = Trades[_tradeId];
        require(_t.closed == false,"trade closed");
        // (address _owner ) = A.getAdvertOwner(_t.advertId);
        // A.adminTransferAsset(_t.advertId, _owner, _t.amount);
        A.addBalance(_t.advertId, _t.amount);
        _t.closed = true;
        emit TradeClosed(_tradeId);
    }

    function adminTransferAsset(string memory _tradeId) external {
        require(msg.sender == ADMIN_ADDRESS,"Unauthorized to make transaction");
        trade storage _t = Trades[_tradeId];
        require(_t.closed == false,"trade closed");
        A.adminTransferAsset(_t.advertId,msg.sender, _t.buyer, _t.amount);
        _t.closed = true;
        emit TradeClosed(_tradeId);
    }

}
